UPDATE vocabulary v JOIN ext_map m ON LOWER(TRIM(v.word)) = m.word
SET v.extensions = m.extensions
WHERE v.extensions IS NULL OR v.extensions = '';
SELECT COUNT(*) AS still_empty FROM vocabulary WHERE extensions IS NULL OR extensions = '';
DROP TEMPORARY TABLE ext_map;
